import sys,numpy as np
sys.path.insert(0,'/opt/tools');from rcb_client import Robot
r=Robot();s=r.spec();o=r.get_obs(depth=True,video='none');c='egocentric_mirrored_camera';im=o.last[c];d=o.last_depth[c];K=np.array(s['cameras'][c]['intrinsic_cv']);E=np.array(o.meta['cameras'][c]['extrinsic_cv']);Ei=np.linalg.inv(E[:,:3]);
for name,box in {'head':(575,50,625,82),'stem':(600,78,625,105)}.items():
 x0,y0,x1,y1=box;reg=im[y0:y1,x0:x1];mask=(reg[:,:,0]>110)&(reg[:,:,0]>reg[:,:,1]*1.15)&(reg[:,:,2]>reg[:,:,1]*1.07)&(reg[:,:,0]>reg[:,:,2]*.82);yy,xx=np.where(mask);pts=[];uv=[]
 for y,x in zip(yy+y0,xx+x0):
  z=float(d[y,x]);
  if z>0:
   pc=np.array([(x-K[0,2])*z/K[0,0],(y-K[1,2])*z/K[1,1],z]);pts.append(Ei@(pc-E[:,3]));uv.append([x,y])
 print(name,'pixels',int(mask.sum()),'valid',len(pts),'uv median',np.median(uv,axis=0) if uv else None,'xyz median',np.round(np.median(pts,axis=0),3) if pts else None,'xyz min',np.round(np.min(pts,axis=0),3) if pts else None,'max',np.round(np.max(pts,axis=0),3) if pts else None)
print('TCP',np.round(o.meta['proprio']['now'][8:15],3),'gap',o.meta['proprio']['now'][24],'cmd',o.meta['proprio']['now'][15])
